#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;     while (t--) {        ll a, b;        cin >> a >> b;         if (a == b) {            cout << 0 << '\n';            continue;        }         ll ratio;         if (b > a) {            if (b % a != 0) {                cout << -1 << '\n';                continue;            }            ratio = b / a;        } else {            if (a % b != 0) {                cout << -1 << '\n';                continue;            }            ratio = a / b;        }         // check power of 2        if (ratio & (ratio - 1)) {            cout << -1 << '\n';            continue;        }         int cnt = 0;         // count how many times divide by 8, 4, 2        while (ratio > 1) {            if (ratio % 8 == 0) {                ratio /= 8;            } else if (ratio % 4 == 0) {                ratio /= 4;            } else {                ratio /= 2;            }            cnt++;        }         cout << cnt << '\n';    }     return 0;}